import { useState, useEffect } from 'react'
import type { ViewMode } from '@/components/shared/ViewModeSelector'

/**
 * Custom hook for managing view mode state with localStorage persistence
 * @param storageKey - The key to use for localStorage storage
 * @param defaultMode - Default view mode if nothing is stored and not mobile
 * @returns [viewMode, setViewMode] - The current view mode and setter function
 */
export function useViewMode(storageKey: string, defaultMode: ViewMode = 'default') {
  const [viewMode, setViewMode] = useState<ViewMode>(() => {
    if (typeof window === 'undefined') {
      return defaultMode
    }

    const saved = localStorage.getItem(storageKey)
    if (saved && ['default', 'comfortable', 'compact'].includes(saved)) {
      return saved as ViewMode
    }

    // Default to comfortable (card) view on mobile for better touch experience
    const isMobile = window.innerWidth < 640
    return isMobile ? 'comfortable' : defaultMode
  })

  // Save view mode preference to localStorage
  useEffect(() => {
    if (typeof window !== 'undefined') {
      localStorage.setItem(storageKey, viewMode)
    }
  }, [storageKey, viewMode])

  return [viewMode, setViewMode] as const
}

