import { ReactNode } from 'react'
import { TableCell, TableRow } from '@/components/ui/table'
import { DropdownMenu, DropdownMenuContent, DropdownMenuItem, DropdownMenuTrigger } from '@/components/ui/dropdown-menu'
import { Button } from '@/components/ui/button'
import { MoreHorizontal } from 'lucide-react'

export interface CompactRowAction {
  label: string
  icon: ReactNode
  onClick: () => void
  variant?: 'default' | 'destructive'
  separator?: boolean
}

export interface CollectionCompactRowProps {
  title: string
  subtitle?: string
  columns: (string | number | ReactNode)[]
  actions?: CompactRowAction[]
  onClick?: () => void
}

export function CollectionCompactRow({
  title,
  subtitle,
  columns,
  actions,
  onClick
}: CollectionCompactRowProps) {
  return (
    <TableRow className={onClick ? "cursor-pointer hover:bg-muted/50" : ""}>
      {/* Title/Name column */}
      <TableCell className="py-1" onClick={onClick}>
        <div className="flex flex-col -space-y-0.5">
          <span className="text-sm font-medium leading-tight">{title}</span>
          {subtitle && (
            <span className="text-xs text-muted-foreground leading-tight">{subtitle}</span>
          )}
        </div>
      </TableCell>

      {/* Data columns - hidden on mobile */}
      {columns.map((column, index) => (
        <TableCell 
          key={index} 
          className="hidden sm:table-cell py-1 text-right text-sm"
          onClick={onClick}
        >
          {column}
        </TableCell>
      ))}

      {/* Actions column */}
      <TableCell className="py-1">
        {actions && actions.length > 0 && (
          <DropdownMenu>
            <DropdownMenuTrigger asChild>
              <Button variant="ghost" size="sm" className="h-6 w-6 p-0">
                <MoreHorizontal className="h-3 w-3" />
              </Button>
            </DropdownMenuTrigger>
            <DropdownMenuContent align="end">
              {actions.map((action, index) => (
                <DropdownMenuItem
                  key={index}
                  onClick={action.onClick}
                  className={action.variant === 'destructive' ? 'text-destructive focus:text-destructive' : ''}
                >
                  {action.icon}
                  {action.label}
                </DropdownMenuItem>
              ))}
            </DropdownMenuContent>
          </DropdownMenu>
        )}
      </TableCell>
    </TableRow>
  )
}

